import{_ as t,o as a,c as s,ax as o}from"./chunks/framework.Bnt0oLax.js";const u=JSON.parse('{"title":"Configuration","description":"Connector fields — endpoint URL, HTTP method, and routing settings, including which are required","frontmatter":{"description":"Connector fields — endpoint URL, HTTP method, and routing settings, including which are required"},"headers":[],"relativePath":"connectors/configuration.md","filePath":"connectors/configuration.md"}'),i={name:"connectors/configuration.md"};function r(n,e,l,d,h,c){return a(),s("div",null,[...e[0]||(e[0]=[o('<div style="display:none;" hidden data-nosnippet>Are you an LLM? You can read better optimized documentation at /docs/connectors/configuration.md for this page in Markdown format</div><h1 id="configuration" tabindex="-1">Configuration <a class="header-anchor" href="#configuration" aria-label="Permalink to &quot;Configuration&quot;">​</a></h1><p>Every connector requires a name, a destination URL, and an HTTP method. Everything else is optional and depends on what the external API expects.</p><p>The HTTP method you set here is fixed for this connector. Every SDK call must use the same method — the platform rejects requests that use a different method than the one configured.</p><h2 id="required-fields" tabindex="-1">Required fields <a class="header-anchor" href="#required-fields" aria-label="Permalink to &quot;Required fields&quot;">​</a></h2><ul><li><strong>Connection Name</strong>: Unique, descriptive name tied to the system or use case. Use names like &quot;Salesforce Case Creation&quot; or &quot;Weather API Current Conditions&quot; — avoid generic labels like &quot;API&quot; or &quot;Test&quot;. The platform derives a <a href="#permalink">permalink</a> from this name.</li><li><strong>Endpoint URL</strong>: Full HTTPS endpoint. Supports template expressions in the path and query string — for example: <code><a href="https://api.example.com/users/&amp;#123;&amp;#123" target="_blank" rel="noreferrer">https://api.example.com/users/{&amp;#123</a>; user.id }}/profile</code>. The host accepts <code>get_variable()</code>, optionally with a <code>default()</code> fallback — see <a href="#templating-the-host">Templating the host</a>. The protocol cannot be templated. Non-templated URLs must be HTTPS and cannot target localhost or private IP ranges.</li><li><strong>HTTP Method</strong>: <code>GET</code>, <code>POST</code>, <code>PUT</code>, <code>PATCH</code>, <code>DELETE</code>, <code>HEAD</code>, or <code>OPTIONS</code>.</li></ul><h2 id="optional-fields" tabindex="-1">Optional fields <a class="header-anchor" href="#optional-fields" aria-label="Permalink to &quot;Optional fields&quot;">​</a></h2><ul><li><strong>Headers</strong>: Content type, API versions, or custom headers. See <a href="./headers-and-query-parameters.html">Headers &amp; Query Parameters</a>.</li><li><strong>Query Parameters</strong>: Search filters, pagination, or API keys. See <a href="./headers-and-query-parameters.html">Headers &amp; Query Parameters</a>.</li><li><strong>Authentication Type</strong>: API Key, OAuth Client Credentials, JWT, or OAuth JWT Bearer. Always use <a href="./secrets/">Secrets and Variables</a> for credential values. See <a href="./authentication.html">Authentication</a>.</li><li><strong>Request Transformation</strong>: Template to reshape the request body for POST/PUT/PATCH requests. See <a href="./payload-template.html">Request Transformation</a>.</li><li><strong>Response Body</strong>: Template to transform the upstream response before returning it to the widget. See <a href="./response-transformation.html">Response Transformation</a>.</li><li><strong>Response Content-Type</strong>: Override the Content-Type header on the response returned to the widget.</li></ul><h2 id="templating-the-host" tabindex="-1">Templating the host <a class="header-anchor" href="#templating-the-host" aria-label="Permalink to &quot;Templating the host&quot;">​</a></h2><p>The host portion of the Endpoint URL accepts <code>get_variable()</code>, optionally wrapped in a <code>default()</code> fallback. No other template expression is valid there.</p><table tabindex="0"><thead><tr><th>Form</th><th>Example</th><th>Valid</th></tr></thead><tbody><tr><td>Host from a Variable</td><td><code>https://{{ get_variable(&#39;portal_host&#39;) }}/api/v2</code></td><td>Yes</td></tr><tr><td>Whole origin from a Variable</td><td><code>{{ get_variable(&#39;instance_url&#39;) }}/services/data</code></td><td>Yes</td></tr><tr><td>Host from a Variable, with a fallback</td><td><code>https://{{ get_variable(&#39;portal_host&#39;) | default(&#39;app.example.com&#39;, true) }}/api/v2</code></td><td>Yes</td></tr><tr><td>One label of the host from a Variable</td><td><code>https://{{ get_variable(&#39;region&#39;) }}.api.example.com/v1</code></td><td>Yes</td></tr><tr><td>Any other expression in the host</td><td><code>https://{{ user.id }}.example.com/v1</code></td><td>No</td></tr><tr><td>Templated protocol</td><td><code>{{ get_variable(&#39;scheme&#39;) }}://api.example.com</code></td><td>No</td></tr></tbody></table><p><code>get_variable()</code> must be called with a quoted name. Apart from <code>default()</code>, described below, nothing else may be applied to it: another filter (<code>{{ get_variable(&#39;host&#39;) | upper }}</code>), a name held in another expression (<code>{{ get_variable(name) }}</code>), or a conditional makes the URL invalid. The rejection message names the expression that caused it.</p><h3 id="falling-back-to-a-default-host" tabindex="-1">Falling back to a default host <a class="header-anchor" href="#falling-back-to-a-default-host" aria-label="Permalink to &quot;Falling back to a default host&quot;">​</a></h3><p><code>default()</code> is the one filter allowed in the host. Use it when most communities should share a host and only some override it:</p><div class="language-jinja2 vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">jinja2</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">https://</span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">{{ </span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">get_variable</span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;portal_host&#39;</span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">) | </span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">default</span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;app.example.com&#39;</span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">) }}</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">/api/v2</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>Its arguments must be written literally — a quoted string, optionally followed by <code>true</code>, and nothing else. An argument that reads another value, such as <code>default(user.email)</code>, is rejected, as is any other number or type of argument.</p><p>When the Variable supplies the whole origin rather than just the host, the fallback has to carry the protocol too — <code>default(&#39;https://app.example.com&#39;)</code>, not <code>default(&#39;app.example.com&#39;)</code>. A fallback without it produces a URL with no protocol, which fails when the connector runs.</p><p>The second argument matters. With <code>true</code>, a Variable set to an empty value also falls back. Without it, only a Variable that has never been set falls back, and an empty one produces a URL with no host, which fails when the connector runs.</p><div class="warning custom-block"><p class="custom-block-title">A default hides a misspelled Variable name</p><p>When a default is present, a Variable name that does not match anything no longer produces an error — the connector quietly uses the fallback host. That is what a default is for, but it means a typo can send live traffic to the wrong host silently. Use <strong>Test Connection</strong> to confirm the resolved URL is the one you expect.</p></div><p>A templated host is checked when the connector runs, not when it is saved. The request fails if the host resolves to a non-HTTPS URL, to <code>localhost</code>, or to a private IP range — whether that value came from the Variable or from a <code>default()</code>. Without a default, a Variable that does not exist also fails, because the placeholder is left unresolved. Use <strong>Test Connection</strong> to see the resolved URL before relying on it.</p><p>Composite connector steps follow the same rules.</p><h2 id="permalink" tabindex="-1">Permalink <a class="header-anchor" href="#permalink" aria-label="Permalink to &quot;Permalink&quot;">​</a></h2><p>The <strong>permalink</strong> is a URL-safe identifier derived from the Connection Name (lowercase, spaces replaced by hyphens). You use it when calling the connector from widget code:</p><div class="language-javascript vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">javascript</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">sdk.connectors.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">execute</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">({ permalink: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;weather-api&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, method: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;GET&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> });</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><div class="info custom-block"><p class="custom-block-title">URL template limitations</p><p>URL templates render without access to secrets — use <a href="./headers-and-query-parameters.html">Headers &amp; Query Parameters</a> or <a href="./authentication.html">Authentication</a> fields for credentials instead. A non-sensitive value in the URL, such as a per-environment host, comes from a <strong>Variable</strong> with <code>get_variable()</code>. See <a href="./secrets/">Secrets and Variables</a> for details.</p></div><h2 id="next-steps" tabindex="-1">Next Steps <a class="header-anchor" href="#next-steps" aria-label="Permalink to &quot;Next Steps&quot;">​</a></h2><ul><li><a href="./authentication.html">Authentication</a> — Configure API keys or OAuth</li><li><a href="./headers-and-query-parameters.html">Headers &amp; Query Parameters</a> — Add static or overridable values</li><li><a href="./secrets/">Secrets and Variables</a> — Store credentials securely</li></ul>',27)])])}const m=t(i,[["render",r]]);export{u as __pageData,m as default};
